ValidationRule.errorConditionFormula:
AND( ISCHANGED(Status), TEXT(Source_Entity__c) <> "Modon - Egypt",
/* Prevent backward movement */ CASE(PRIORVALUE(Status), "New", 1, "In Progress", 2, "Lead Qualified", 3, "Retired", 4, "Qualified", 5, 0 ) > CASE(Status, "New", 1, "In Progress", 2, "Lead Qualified", 3, "Retired", 4, "Qualified", 5, 0 ),
/* Allow system administrators */ $Profile.Name <> "System Administrator" )
